SELECT DISTINCTROW Richieste.[Numero Record], Richieste.Oli, Richieste.[Anno Archivio], Richieste.[Data richiesta], Richieste.[Data Risposta], Richieste.[Data Ritardo], Richieste.Ritardo, Richieste.Richiedente, Richieste.Produttore, Richieste.Prodotto, Richieste.Cliente, Richieste.Descrizione, Richieste.[Motivo Richiesta], Meccaniche.Oli, Meccaniche.[Peso Specifico], Meccaniche.Vicat, Meccaniche.[Resilienza L], Meccaniche.[Resilienza T], Meccaniche.[All Ca Sn L (%)], Meccaniche.[All Ca Sn T (%)], Meccaniche.[All Rott L (%)], Meccaniche.[All Rott T (%)], Meccaniche.[Ca Sn L (MPa)], Meccaniche.[Ca Sn T (MPa)], Meccaniche.[Ca Rott L (MPa)], Meccaniche.[Ca Rott T (MPa)], Meccaniche.[Mod El Traz L (MPa)], Meccaniche.[Mod El Traz T (MPa)], Meccaniche.Rugosità, Meccaniche.Riflettenza, Meccaniche.Bagnabilità, Meccaniche.Ritiro, Meccaniche.[Lacerazione L], Meccaniche.[Lacerazione T], Meccaniche.[Durezza Shore], Meccaniche.Adesione, Meccaniche.Permeabilità, Meccaniche.[Analisi Termomeccanca], Meccaniche.[Profilo spessori], Meccaniche.Commenti, [Chimiche-Barriera].Oli, [Chimiche-Barriera].[Natura Chimica], [Chimiche-Barriera].Inerti, [Chimiche-Barriera].[Numero K], [Chimiche-Barriera].VCM, [Chimiche-Barriera].Stabilizzazione, [Chimiche-Barriera].[Delta Colore], [Chimiche-Barriera].PermeabilitàA, [Chimiche-Barriera].PermeabilitàB, [Chimiche-Barriera].Altro1, [Chimiche-Barriera].Altro2, [Chimiche-Barriera].Altro3, [Chimiche-Barriera].Altro4
FROM Richieste INNER JOIN (Meccaniche INNER JOIN [Chimiche-Barriera] ON Meccaniche.Oli = [Chimiche-Barriera].Oli) ON (Richieste.Oli = Meccaniche.Oli) AND (Richieste.Oli = [Chimiche-Barriera].Oli)
WHERE ((Richieste.Oli=[Schede]![SRichieste]![Oli]) AND ([Chimiche-Barriera].Oli=[Schede]![SRichieste]![Oli]));
